class Solution {
    public String crushRuns(String s, int k) {
        StringBuilder t = new StringBuilder(s);
        boolean changed = true;
        while (changed) {
            changed = false;
            int run = 1;
            for (int i = 1; i < t.length(); i++) {
                run = t.charAt(i) == t.charAt(i - 1) ? run + 1 : 1;
                if (run == k) {
                    t.delete(i - k + 1, i + 1);
                    changed = true;
                    break;
                }
            }
        }
        return t.toString();
    }
}

