    char* t = malloc(n + 1);
    memcpy(t, s, n + 1);
    bool changed = true;
    while (changed) {
        changed = false;
        int run = 1, len = strlen(t);
        for (int i = 1; i < len; i++) {
            run = t[i] == t[i - 1] ? run + 1 : 1;
            if (run == k) {
                memmove(t + i - k + 1, t + i + 1, len - i);
                changed = true;
                break;
            }
        }
    }
    return t;
