class Solution {
    public String crushRuns(String s, int k) {
        int n = s.length(), top = 0;
        char[] tile = new char[n];
        int[] count = new int[n];
        for (char c : s.toCharArray()) {
            if (top > 0 && tile[top - 1] == c) {
                if (++count[top - 1] == k) top--;
            } else {
                tile[top] = c;
                count[top++] = 1;
            }
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < top; i++) for (int j = 0; j < count[i]; j++) out.append(tile[i]);
        return out.toString();
    }
}

