class Solution {
public:
    string crushRuns(string& s, int k) {
        vector<pair<char, int>> stack;
        for (char c : s) {
            if (!stack.empty() && stack.back().first == c) {
                if (++stack.back().second == k) stack.pop_back();
            } else {
                stack.push_back({c, 1});
            }
        }
        string out;
        for (auto& [c, cnt] : stack) out.append(cnt, c);
        return out;
    }
};

