char* crushRuns(char* s, int k) {
    int n = strlen(s), top = 0;
    char* tile = malloc(n + 1);
    int* count = malloc((n + 1) * sizeof(int));
    for (int i = 0; i < n; i++) {
        if (top > 0 && tile[top - 1] == s[i]) {
            if (++count[top - 1] == k) top--;
        } else {
            tile[top] = s[i];
            count[top++] = 1;
        }
    }
    char* out = malloc(n + 1);
    int w = 0;
    for (int i = 0; i < top; i++) for (int j = 0; j < count[i]; j++) out[w++] = tile[i];
    out[w] = '\0';
    free(tile);
    free(count);
    return out;
}
